ae:processModel.ae:script:
a!localVariables(
  /* Divide i destinatari su ';' e crea lista utenti/email */
  local!recipientList: a!forEach(
    items: split(pp!recipients, ";"),
    expression: trim($item)
  ),

  a!sendEmail(
    to:      local!recipientList,
    subject: pp!alertSubject,
    body:    pp!alertBody,
    /* Aggiungere allegati se necessario:
       attachments: {} */
    onSuccess: {},
    onError: {
      /* Log dell'errore: opzionale - scrivere su custom data store */
    }
  )
)

/*
  Opzionale: scrivere su data store custom per storico alert.
  Decommentare e adattare se si crea l'entità AON_PERF_AlertLog.

  a!writeToDataStore(
    dataStore: cons!AON_PERF_DATA_STORE,
    entities: {
      {
        _type:      type!AON_PERF_AlertLog,
        sentAt:     now(),
        subject:    pp!alertSubject,
        recipients: pp!recipients,
        body:       pp!alertBody
      }
    }
  )
*/
null()
